const crypto = require('crypto');
const timestamp = $json.headers?.['x-erp-timestamp'];
const received = $json.headers?.['x-erp-signature'];
const raw = $json.rawBody || JSON.stringify($json.body || {});
if (!timestamp || !received || Math.abs(Date.now() / 1000 - Number(timestamp)) > 300) throw new Error('Solicitud vencida o incompleta');
const expected = 'sha256=' + crypto.createHmac('sha256', $env.ERP_RAG_WEBHOOK_SECRET).update(`${timestamp}.${raw}`).digest('hex');
const receivedBuffer = Buffer.from(received); const expectedBuffer = Buffer.from(expected);
if (receivedBuffer.length !== expectedBuffer.length || !crypto.timingSafeEqual(receivedBuffer, expectedBuffer)) throw new Error('Firma HMAC inválida');
const request = $json.body || {};
if (!request.tenant_id || !request.user_id || !request.message) throw new Error('Solicitud de chat incompleta');
return [{ json: { ...request, conversation_id: request.conversation_id || `${request.tenant_id}:${request.user_id}` } }];

const embedding = $json.embedding?.values;
const request = $('Verificar solicitud ERP').first().json;
if (!Array.isArray(embedding) || embedding.length !== 768) throw new Error('Embedding de consulta inválido');
return [{ json: { query_embedding: embedding, match_tenant_id: request.tenant_id, match_count: 8, match_threshold: 0.55 } }];

const request = $('Verificar solicitud ERP').first().json;
const history = $('Cargar memoria de conversación').all().flatMap(({ json }) => Array.isArray(json) ? json : (Array.isArray(json.data) ? json.data : [json])).filter((m) => m.role && m.content).reverse();
const found = $input.all().flatMap(({ json }) => Array.isArray(json) ? json : (Array.isArray(json.data) ? json.data : [json])).filter((d) => d.title && d.content).slice(0, 8);
const context = found.map((d, i) => `[${i + 1}] ${d.title}: ${d.content}`).join('

') || 'No hay datos empresariales indexados relevantes para esta consulta.';
const memory = history.map((m) => `${m.role === 'assistant' ? 'Asistente' : 'Usuario'}: ${m.content}`).join('
') || 'Sin mensajes previos.';
const system = `Eres EnterpriseCloud Assistant, el asistente interno y profesional del ERP. Atiendes únicamente consultas sobre la empresa activa y sobre ventas, compras, inventario, productos, clientes, proveedores, tesorería, cuentas por cobrar/pagar, conciliación, documentos, reportes, notificaciones y administración permitida.

OBJETIVO: ayuda a interpretar información del ERP, explicar procesos y orientar al módulo adecuado. Responde en español claro, profesional y conciso.

SEGURIDAD: usa exclusivamente el CONTEXTO ERP para cifras, stock, estados y datos concretos. No inventes información ni afirmes que una acción se ejecutó. No reveles claves, tokens, datos de otros usuarios, configuraciones técnicas, embeddings, RAG, Supabase o n8n. El usuario ya inició sesión: no pidas datos personales. Puedes explicar cómo registrar o consultar datos, pero no ejecutes ventas, pagos, eliminaciones, permisos ni asientos. Si falta evidencia, dilo y señala el módulo o filtro pertinente. Si la consulta es ajena al ERP, redirígela brevemente.

MEMORIA:
${memory}

CONTEXTO ERP:
${context}`;
return [{ json: { model: $env.DEEPSEEK_CHAT_MODEL || 'deepseek-chat', temperature: 0.2, max_tokens: 700, messages: [{ role: 'system', content: system }, ...history.map((m) => ({ role: m.role, content: m.content })), { role: 'user', content: request.message }], sources: found.map((d) => ({ title: d.title, similarity: d.similarity, source: d.metadata?.source })) } }];

const request = $('Verificar solicitud ERP').first().json;
const answer = $('Formatear respuesta').first().json.answer;
return [{ json: { tenant_id: request.tenant_id, user_id: request.user_id, conversation_id: request.conversation_id, role: 'user', content: request.message } }, { json: { tenant_id: request.tenant_id, user_id: request.user_id, conversation_id: request.conversation_id, role: 'assistant', content: answer } }];
